import { useEffect, useState } from "react";
import { Box, Container, Stack, Typography } from "@mui/material";
import api, { mediaUrl } from "../services/api";
import type { HomeFeature, ListResponse } from "../types/home";

export default function Features() {
  const [items, setItems] = useState<HomeFeature[]>([]);

  useEffect(() => {
    api
      .get<ListResponse<HomeFeature>>("/home-features", {
        params: { "sort[0]": "order:asc", populate: "image" },
      })
      .then((payload) => setItems(payload.data || []))
      .catch(() => setItems([]));
  }, []);

  if (!items.length) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 10 }, backgroundColor: "#fff" }}>
      <Container maxWidth="lg">
        <Stack spacing={8}>
          {items.map((item) => {
            const image = mediaUrl(item.image);
            const imageFirst = item.imageOnRight === false;
            return (
              <Stack
                key={item.id || item.number}
                direction={{ xs: "column", md: imageFirst ? "row" : "row-reverse" }}
                alignItems="center"
                spacing={4}
              >
                <Box sx={{ flex: 1 }}>
                  <Typography sx={{ color: "#759ae1", fontSize: 54, fontWeight: 900, lineHeight: 1.2 }}>
                    {item.number}
                  </Typography>
                  <Typography sx={{ color: "#17224d", fontSize: { xs: 26, md: 36 }, fontWeight: 600, mb: 1.5 }}>
                    {item.title}
                  </Typography>
                  <Typography sx={{ color: "#5a6473", fontSize: 16, lineHeight: 1.65 }}>
                    {item.description}
                  </Typography>
                </Box>
                {image ? (
                  <Box sx={{ flex: 1, textAlign: "center" }}>
                    <Box
                      component="img"
                      src={image}
                      alt={item.image?.alternativeText || item.title}
                      sx={{ width: "100%", maxWidth: 480 }}
                    />
                  </Box>
                ) : null}
              </Stack>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
